mapper.select:
SELECT id, kind, start_at, end_at, start_date, end_date, title
FROM schedule
WHERE user_id = #{userId}
AND (
    (
        kind = 'ALL_DAY'
        AND start_date <= #{endDate}
        AND end_date >= #{startDate}
    )
    OR
    (
        kind = 'DATED'
        AND CAST(start_at AS DATE) <= #{endDate}
        AND CAST(end_at AS DATE) >= #{startDate}
    )
)

SELECT id, kind, start_at, end_at, start_date, end_date, title
FROM schedule
WHERE id = #{id}

SELECT
    c.id, c.schedule_id, c.color, c.memo,
    s.kind, s.start_at, s.end_at, s.start_date, s.end_date, s.title
FROM calendar_event c
INNER JOIN schedule s ON c.schedule_id = s.id
WHERE s.user_id = #{userId}
AND (
    (
        s.kind = 'ALL_DAY'
        AND s.start_date <= #{endDate}
        AND s.end_date >= #{startDate}
    )
    OR
    (
        s.kind = 'DATED'
        AND CAST(s.start_at AS DATE) <= #{endDate}
        AND CAST(s.end_at AS DATE) >= #{startDate}
    )
)
